css:
.imf {
  --ink: #131F2B;
  --ink-soft: #47585F;
  --ink-faint: #6E7C82;
  --paper: #E3E7DF;
  --paper-raised: #EEF0E9;
  --paper-card: #F3F4EE;
  --accent: #004C97;
  --accent-strong: #003B78;
  --accent-deep: #0F6E8C;
  --imf: #004C97;
  --imf-light: #2A72BD;
  --imf-teal: #2BB3A8;
  --imf-green: #8FD26B;
  --line: rgba(19, 31, 43, 0.16);
  --line-strong: rgba(19, 31, 43, 0.32);
  --shadow: 0 18px 40px -22px rgba(19, 31, 43, 0.35);
  /* ---------- top bar ---------- */
  /* ---------- hero ---------- */
  /* Fill the horizontal-scroll panel (same pattern as orlando-magic.less) */
  /* IMF-style #004c97 → transparent fade */
  /* drifting bars — CSS random(), JS fallback in scripts/hero-bars.js */
}
@media (prefers-color-scheme: dark) {
  .imf :root:not([data-theme="light"]) {
    --ink: #E9E4D3;
    --ink-soft: #B8C4C6;
    --ink-faint: #8698A0;
    --paper: #0A131B;
    --paper-raised: #101E28;
    --paper-card: #132430;
    --accent: #6AA8EC;
    --accent-strong: #8CBDF2;
    --accent-deep: #6FD3C4;
    --line: rgba(233, 228, 211, 0.14);
    --line-strong: rgba(233, 228, 211, 0.28);
    --shadow: 0 18px 40px -22px rgba(0, 0, 0, 0.6);
  }
}
.imf :root[data-theme="dark"] {
  --ink: #E9E4D3;
  --ink-soft: #B8C4C6;
  --ink-faint: #8698A0;
  --paper: #0A131B;
  --paper-raised: #101E28;
  --paper-card: #132430;
  --accent: #6AA8EC;
  --accent-strong: #8CBDF2;
  --accent-deep: #6FD3C4;
  --line: rgba(233, 228, 211, 0.14);
  --line-strong: rgba(233, 228, 211, 0.28);
  --shadow: 0 18px 40px -22px rgba(0, 0, 0, 0.6);
}
.imf .mono {
  font-variant-numeric: tabular-nums;
}
.imf a {
  color: var(--accent-deep);
}
.imf a:focus-visible,
.imf button:focus-visible,
.imf .exhibit:focus-visible {
  outline: 2px solid var(--accent-deep);
  outline-offset: 3px;
}
.imf h1,
.imf h2,
.imf h3 {
  font-family: "Newsreader", Georgia, "Times New Roman", serif;
  font-weight: 500;
  text-wrap: balance;
  margin: 0;
  color: var(--ink);
}
.imf .wrap {
  max-width: 920px;
  margin: 0 auto;
  padding: 0 clamp(20px, 5vw, 48px);
}
.imf .topbar {
  position: sticky;
  top: 0;
  z-index: 40;
  background: color-mix(in srgb, var(--paper) 88%, transparent);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--line);
}
.imf .topbar-inner {
  max-width: 920px;
  margin: 0 auto;
  padding: 14px clamp(20px, 5vw, 48px);
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
}
.imf .topbar::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 3px;
  background: linear-gradient(90deg, var(--imf) 0%, var(--imf-light) 35%, var(--imf-teal) 70%, var(--imf-green) 100%);
}
.imf .topbar .ref {
  font-size: 11px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
  color: var(--ink-faint);
}
.imf .topbar .ref b {
  color: var(--ink-soft);
  font-weight: 500;
}
.imf .topbar .coord {
  font-size: 11px;
  color: var(--ink-faint);
  letter-spacing: 0.03em;
}
.imf.horizontal__panel > .horizontal__panel-inner {
  padding: 0;
  height: 100%;
  display: flex;
  flex-direction: column;
}
.imf.horizontal__panel .hero {
  flex: 1 1 auto;
  min-height: 100%;
  display: flex;
  align-items: center;
}
.imf.horizontal__panel .hero-inner {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
}
.imf .hero {
  position: relative;
  overflow: hidden;
  color: #fff;
  background: radial-gradient(ellipse 55% 85% at 88% 35%, rgba(143, 210, 107, 0.55), transparent 62%), radial-gradient(ellipse 60% 80% at 72% 105%, rgba(43, 179, 168, 0.6), transparent 66%), linear-gradient(110deg, var(--imf) 0%, #0A5BA8 45%, #1B88B2 75%, #3DB39C 100%);
}
.imf .hero-bg {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.imf .hero-sweeps {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.imf .hero-fade {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, var(--imf) 0%, var(--imf) 28%, rgba(0, 76, 151, 0.62) 52%, rgba(0, 76, 151, 0) 100%);
}
.imf .hero-bars {
  position: absolute;
  inset: 0;
  overflow: hidden;
}
.imf .hero-bars .bar {
  position: absolute;
  left: 0;
  display: block;
  border-radius: 2px;
  mix-blend-mode: screen;
  will-change: transform;
  animation-name: hero-drift;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  top: random(-2%, 98%);
  width: random(60px, 380px);
  height: random(3px, 28px);
  background: hsl(random(198, 218) 85% random(62%, 82%) / random(0.06, 0.22));
  animation-duration: random(45s, 150s);
  animation-delay: random(-150s, 0s);
}
.imf .hero-bars .bar:nth-child(even) {
  animation-direction: reverse;
}
@keyframes hero-drift {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(100vw);
  }
}
.imf .hero-inner {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  column-gap: clamp(24px, 5vw, 56px);
  align-items: center;
  padding: clamp(64px, 12vw, 120px) clamp(20px, 5vw, 48px) clamp(48px, 8vw, 76px);
}
.imf .hero-inner > * {
  grid-column: 1;
}
.imf .hero-seal {
  grid-column: 2 !important;
  grid-row: 1 / span 3;
  width: clamp(150px, 22vw, 250px);
  height: auto;
  opacity: 0.92;
  filter: drop-shadow(0 10px 30px rgba(0, 30, 70, 0.35));
}
.imf .hero .meta-row {
  grid-column: 1 / -1;
}
.imf .hero h1 {
  max-width: 13ch;
}
.imf .hero .role {
  max-width: 34ch;
}
@media (max-width: 760px) {
  .imf .hero-inner {
    grid-template-columns: 1fr;
  }
  .imf .hero-seal {
    grid-column: 1 !important;
    grid-row: 1;
    width: 84px;
    margin-bottom: 26px;
  }
  .imf .hero-fade {
    background: linear-gradient(90deg, var(--imf) 0%, rgba(0, 76, 151, 0.75) 60%, rgba(0, 76, 151, 0.35) 100%);
  }
  .imf .hero h1,
  .imf .hero .role {
    max-width: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .imf .hero-bars .bar {
    transform: none;
    left: random(0%, 90%);
  }
}
.imf .eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent-strong);
  margin-bottom: 22px;
}
.imf .eyebrow::before {
  content: "";
  width: 26px;
  height: 1px;
  background: var(--accent);
}
.imf .hero h1 {
  font-family: "Montserrat", "Gotham", "Helvetica Neue", Arial, sans-serif;
  font-weight: 800;
  text-transform: uppercase;
  font-size: clamp(2rem, 5.4vw, 3.6rem);
  line-height: 1.02;
  letter-spacing: 0;
  color: #F4F8FC;
}
.imf .hero .eyebrow {
  color: rgba(255, 255, 255, 0.82);
}
.imf .hero .eyebrow::before {
  background: rgba(255, 255, 255, 0.6);
}
.imf .hero .role {
  margin-top: 18px;
  font-size: clamp(1.05rem, 2.4vw, 1.3rem);
  color: rgba(255, 255, 255, 0.86);
  max-width: 34ch;
  font-family: "Newsreader", serif;
  font-style: italic;
}
.imf .meta-row {
  margin-top: 44px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 22px 32px;
  padding-top: 24px;
  border-top: 1px solid var(--line);
}
.imf .hero .meta-row {
  border-top-color: rgba(255, 255, 255, 0.28);
}
.imf .hero .meta-item .label {
  color: rgba(255, 255, 255, 0.66);
}
.imf .hero .meta-item .value {
  color: #fff;
}
.imf .meta-item .label {
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--ink-faint);
  margin-bottom: 6px;
}
.imf .meta-item .value {
  font-size: 14.5px;
  color: var(--ink);
}
@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}
